// Compact summarizer for a captured conversation jsonl (read from stdin).
import { createInterface } from 'node:readline';
const rl = createInterface({ input: process.stdin });
const rows = [];
for await (const line of rl) {
  let e; try { e = JSON.parse(line); } catch { continue; }
  const t = e.timestamp || '';
  const short = t ? t.slice(11, 19) : '--------';
  if (e.type === 'user' && e.message) {
    const c = e.message.content;
    if (typeof c === 'string') rows.push([short, 'USER', c.replace(/\s+/g, ' ').slice(0, 700)]);
    else if (Array.isArray(c)) {
      for (const b of c) {
        if (b.type === 'text') rows.push([short, 'USER', b.text.replace(/\s+/g, ' ').slice(0, 700)]);
        else if (b.type === 'tool_result') {
          const txt = typeof b.content === 'string' ? b.content : JSON.stringify(b.content || '');
          const err = b.is_error ? 'ERR' : 'res';
          rows.push([short, err, txt.replace(/\s+/g, ' ').slice(0, b.is_error ? 400 : 130)]);
        }
      }
    }
  } else if (e.type === 'assistant' && e.message) {
    for (const b of e.message.content || []) {
      if (b.type === 'text') rows.push([short, 'AGENT', b.text.replace(/\s+/g, ' ').slice(0, 700)]);
      else if (b.type === 'tool_use') {
        const inp = JSON.stringify(b.input || {}).replace(/\s+/g, ' ').slice(0, 220);
        rows.push([short, 'TOOL', `${b.name} ${inp}`]);
      }
    }
  }
}
for (const [t, k, v] of rows) console.log(`${t} ${k.padEnd(5)} ${v}`);
console.error(`entries=${rows.length}`);

